package com.vit.archds.controller; import com.vit.archds.dto.ProjectDtos.JobResponse; import com.vit.archds.service.AnalysisService; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/jobs") public class JobController { private final AnalysisService a; public JobController(AnalysisService x){a=x;} @GetMapping("/{jobId}") public JobResponse get(@PathVariable String jobId){var j=a.get(jobId);return new JobResponse(j.getJobId(),j.getStatus().name(),j.getProgress(),j.getCurrentStage(),j.getMessage(),j.getErrorMessage(),j.getCreatedAt(),j.getStartedAt(),j.getCompletedAt());}}
